parameters.jsCode:
const TEAM = {
  andrii: { name: 'Андрій', role: 'менеджер підтримки', tg: '@hb_andrii' },
  iryna:  { name: 'Ірина', role: 'менеджерка повернень', tg: '@hb_iryna' },
  maryna: { name: 'Марина', role: 'бухгалтерка', tg: '@hb_maryna' },
  olena:  { name: 'Олена', role: 'старша менеджерка (тімлідка)', tg: '@hb_olena' },
  dmytro: { name: 'Дмитро', role: 'власник', tg: '@hb_dmytro' },
  none:   { name: '—', role: 'спам, без власника', tg: '' },
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Плоский тікет + валідація відповіді AI (для кожного листа окремо)
const ctx = $('Collect Ticket Context').item.json;
const o = $json.output ?? {};

const SLA = { P1: 30, P2: 120, P3: 240, P4: 1440 };
const CATEGORY_OWNER = { 'доставка': 'andrii', 'повернення_брак': 'iryna', 'оплата': 'maryna', 'товар_b2b': 'olena', 'спам': 'none' };

const category = Object.keys(CATEGORY_OWNER).includes(o.category) ? o.category : 'товар_b2b';
let priority = Object.keys(SLA).includes(o.priority) ? o.priority : 'P2';   // незрозуміло -> P2, людина подивиться
if (o.is_vip === true && ['P3', 'P4'].includes(priority) && category !== 'спам') priority = 'P2'; // правило VIP
if (category === 'спам') priority = 'P4';
let owner = TEAM[o.owner] ? o.owner : CATEGORY_OWNER[category];
if (category === 'спам') owner = 'none';
if (category !== 'спам' && owner === 'none') owner = 'olena';          // default owner

const slaMinutes = category === 'спам' ? 0 : SLA[priority];             // SLA рахує код, а не AI
const created = DateTime.fromISO(ctx.created_at).setZone('Europe/Kyiv');
const deadline = category === 'спам' ? '' : created.plus({ minutes: slaMinutes }).toISO();
const reasoning = (o.reasoning || '').trim() || 'AI не надав обґрунтування — перевірити вручну.';
const sentiment = ['positive', 'neutral', 'frustrated', 'angry'].includes(o.customer_sentiment) ? o.customer_sentiment : 'neutral';
const who = TEAM[owner];
const icon = { P1: '🔴', P2: '🟠', P3: '🟡', P4: '⚪' }[priority];

const tg_text =
  `${icon} <b>Новий тікет — ${priority}${o.is_vip ? ' · VIP' : ''}</b>\n` +
  `👤 <b>Власник:</b> ${esc(who.name)} (${esc(who.role)}) ${esc(who.tg)}\n` +
  `📂 <b>Категорія:</b> ${esc(category)}\n` +
  `⏱ <b>SLA:</b> ${slaMinutes} хв (до ${created.plus({ minutes: slaMinutes }).toFormat('dd.MM HH:mm')})\n` +
  `💬 <b>Тональність:</b> ${esc(sentiment)}\n\n` +
  `<b>Тема:</b> ${esc(ctx.subject)}\n<b>Від:</b> ${esc(ctx.from_email)}\n\n` +
  `<b>Що сталося:</b> ${esc(o.summary)}\n\n` +
  `🧠 <b>Чому такий пріоритет (AI):</b>\n<i>${esc(reasoning)}</i>\n\n` +
  `<a href="${ctx.thread_link}">→ Відкрити лист</a>`;

return {
  json: {
    ticket_id: ctx.ticket_id,
    created_at: created.toISO(),
    from_email: ctx.from_email,
    subject: ctx.subject,
    category,
    priority,
    owner,
    sla_minutes: slaMinutes,
    sla_deadline: deadline,
    status: category === 'спам' ? 'closed' : 'open',
    summary: o.summary || '',
    reasoning,
    sentiment,
    thread_link: ctx.thread_link,
    escalation_level: '',
    escalated_at: '',
    tg_text,
  },
};

const TEAM = {
  andrii: { name: 'Андрій', role: 'менеджер підтримки', tg: '@hb_andrii' },
  iryna:  { name: 'Ірина', role: 'менеджерка повернень', tg: '@hb_iryna' },
  maryna: { name: 'Марина', role: 'бухгалтерка', tg: '@hb_maryna' },
  olena:  { name: 'Олена', role: 'старша менеджерка (тімлідка)', tg: '@hb_olena' },
  dmytro: { name: 'Дмитро', role: 'власник', tg: '@hb_dmytro' },
  none:   { name: '—', role: 'спам, без власника', tg: '' },
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Рівень ескалації для кожного відкритого тікета з простроченим SLA.
// L0: 0–29 хв після breach -> нагадування власнику; L1: 30–59 хв -> тімлідка Олена; L2: 60+ хв -> лист власнику.
// Надсилаємо лише якщо рівень ВИЩИЙ за вже зафіксований у таблиці (без повторів кожні 5 хв).
const now = DateTime.now().setZone('Europe/Kyiv');
const out = [];
for (const item of $input.all()) {
  const t = item.json;
  if (!t.sla_deadline || !t.ticket_id) continue;
  const deadline = DateTime.fromISO(String(t.sla_deadline));
  if (!deadline.isValid) continue;
  const overdue = Math.floor(now.diff(deadline, 'minutes').minutes);
  if (overdue < 0) continue;                                    // SLA ще не порушено
  const level = overdue >= 60 ? 2 : overdue >= 30 ? 1 : 0;
  const prev = t.escalation_level === '' || t.escalation_level === undefined ? -1 : Number(t.escalation_level);
  if (level <= prev) continue;                                  // цей рівень уже надсилали

  const who = TEAM[t.owner] ?? TEAM.olena;
  const head = `<b>Тема:</b> ${esc(t.subject)}\n<b>Від:</b> ${esc(t.from_email)}\n<b>Категорія:</b> ${esc(t.category)} · ${esc(t.sentiment)}\n<b>Резюме:</b> ${esc(t.summary)}`;
  const tg_text = level === 0
    ? `⏰ <b>L0 · Нагадування власнику — SLA прострочено</b>\n\n${esc(who.name)} ${esc(who.tg)}, тікет <b>${esc(t.priority)}</b> чекає на відповідь уже на <b>${overdue} хв</b> довше за SLA (${esc(t.sla_minutes)} хв).\n\n${head}\n\n<a href="${t.thread_link}">→ Взяти в роботу</a>`
    : `🚨 <b>L1 · Ескалація тімлідці</b>\n\nОлена @hb_olena, тікет <b>${esc(t.priority)}</b> прострочено на <b>${overdue} хв</b>. Власник ${esc(who.name)} (${esc(who.role)}) не зреагував на нагадування.\n\n${head}\n\n🧠 <b>Reasoning AI:</b> <i>${esc(t.reasoning)}</i>\n\n<a href="${t.thread_link}">→ Допомогти або перепризначити</a>`;

  out.push({
    json: {
      ...t,
      owner_name: who.name,
      minutes_overdue: overdue,
      escalation_level: level,
      escalated_at: now.toISO(),
      tg_text,
    },
  });
}
return out;
